#wsc-section-wrapper{width:100%;display:flex;justify-content:center;align-items:center;background:transparent;padding:20px 0;font-family:'Quicksand',sans-serif}#wsc-container{width:95%;max-width:380px;background:#fff;padding:25px;border-radius:25px;box-shadow:0 10px 30px rgba(0,0,0,.05);border:1px solid #fdf0f5;box-sizing:border-box;overflow:hidden}.wsc-art-title{text-align:center;margin:0;font-family:'Great Vibes',cursive;font-size:1.8rem;font-weight:400;line-height:1.2;padding-top:5px;color:rgba(170, 1, 1, 1);display:block}.wsc-art-subtitle{text-align:center;font-size:13px;color:#666;margin:12px 0 22px;line-height:1.5;padding:0 10px;font-style:italic}#wsc-form{display:flex;flex-direction:column;gap:10px}#wsc-form input,#wsc-attendance{padding:12px 15px;border:1.5px solid #e0e6ed;border-radius:10px;outline:0;font-size:14px;background:#fffafa;width:100%;box-sizing:border-box;color:#4a4a4a;font-family:'Quicksand',sans-serif}#wsc-form input:focus,#wsc-attendance:focus{border-color:rgba(170, 1, 1, 1);background:#fff}#wsc-sendBtn{padding:12px;background:rgba(170, 1, 1, 1);color:#fff;border:none;border-radius:10px;font-weight:600;cursor:pointer;font-family:'Quicksand',sans-serif;font-size:14px;margin-top:5px;transition:all .3s ease}#wsc-sendBtn:hover{opacity:.9;transform:translateY(-1px)}#wsc-success-msg{display:none;flex-direction:column;align-items:center;justify-content:center;position:fixed;top:0;left:0;width:100vw;height:100vh;background:rgba(255,255,255,.7);backdrop-filter:blur(5px);z-index:99999}#wsc-success-msg .wsc-msg-box{background:#fff;padding:30px;border-radius:20px;box-shadow:0 15px 45px rgba(170, 1, 1,.2);border:2px solid #e0e6ed;display:flex;flex-direction:column;align-items:center;gap:15px;width:280px;text-align:center}#wsc-success-msg span{color:rgba(170, 1, 1, 1);font-weight:600;font-size:15px;line-height:1.5}#wsc-ok-btn{padding:8px 40px;background:rgba(170, 1, 1, 1);color:#fff;border:none;border-radius:20px;font-weight:700;cursor:pointer;font-family:'Quicksand',sans-serif}#wsc-list{margin-top:15px;height:240px;overflow-y:auto;border-top:1px solid #fdf0f5;padding-top:10px;scrollbar-width:none}#wsc-list::-webkit-scrollbar{display:none}.wsc-item{background:#f4f7fa;padding:10px;border-radius:10px;margin-bottom:8px;border-left:4px solid rgba(170, 1, 1, 1);text-align:left}.wsc-item strong{display:block;color:rgba(170, 1, 1, 1);font-size:15px;font-weight:700}.wsc-item span{color:#555;font-size:14px;line-height:1.4}.wsc-loading{text-align:center;color:#bbb;font-size:12px;padding:15px 0}#wsc-fireworks{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:10000;display:none}
